import re
from fractions import Fraction as F
e1="57-33/11*13-2"; e2="64-56/8*4-44"
opts={'A':(2,4),'B':(56,57),'C':(57,64),'D':(33,44)}
def swap(e,a,b):
    toks=re.findall(r'\d+|\D',e)
    return ''.join(str(b) if t==str(a) else str(a) if t==str(b) else t for t in toks)
def val(a,b):
    x=eval(swap(e1,a,b)); y=eval(swap(e2,a,b))
    return F(2)**int(x)+F(3)**int(y) if x==int(x) and y==int(y) else None
res={k:val(*v) for k,v in opts.items()}
assert res['D']==35
for k in 'ABC': assert res[k]!=35

def fold(net):
    start=next(iter(net))
    # orientation: vectors for face normal, 'down' (row+1) dir, 'right' (col+1) dir
    res={}
    def neg(v): return tuple(-x for x in v)
    stack=[(start,(0,0,1),(0,-1,0),(1,0,0))]
    seen=set()
    while stack:
        c,n,d,r=stack.pop()
        if c in seen: continue
        seen.add(c); res[net[c]]=n
        (i,j)=c
        for (di,dj) in [(1,0),(-1,0),(0,1),(0,-1)]:
            nc=(i+di,j+dj)
            if nc not in net or nc in seen: continue
            if (di,dj)==(1,0): stack.append((nc,d,neg(n),r))
            if (di,dj)==(-1,0): stack.append((nc,neg(d),n,r))
            if (di,dj)==(0,1): stack.append((nc,r,d,neg(n)))
            if (di,dj)==(0,-1): stack.append((nc,neg(r),d,n))
    return res
net={(0, 1): '#', (0, 0): '@', (1, 1): '%', (2, 1): '€', (3, 1): '∞', (3, 2): '*'}
f=fold(net)
opp=[k for k,v in f.items() if tuple(-x for x in v)==f['#']][0]
opts={'A': '@', 'B': '∞', 'C': '€', 'D': '%'}
assert opp==opts['C']
for k,v in opts.items():
    if k!='C': assert opp!=v

